class Solution:
    def calculate(self, s: str) -> int:
        st = []; res = 0; sign = 1; num = 0
        for c in s:
            if c.isdigit(): num = num * 10 + int(c)
            elif c in "+-":
                res += sign * num; num = 0; sign = 1 if c == "+" else -1
            elif c == "(":
                st.append((res, sign)); res, sign = 0, 1
            elif c == ")":
                res += sign * num; num = 0
                pr, ps = st.pop(); res = pr + ps * res
        return res + sign * num

